#include <iostream>
#include <optional>
#include <vector>

std::optional<int> best(const std::vector<int>& scores) {
    if (scores.empty()) return std::nullopt;
    int top = scores[0];
    for (int s : scores) {
        if (s > top) top = s;
    }
    return top;
}

int main() {
    std::vector<int> scores;
    std::cout << "Best: " << best(scores).value() << "\n";
}

